// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title IoTDeviceRegistry
 * @notice Manages IoT device firmware updates with graceful shutdown
 * @dev Implements a two-phase commit for firmware transitions
 */
contract IoTDeviceRegistry {
    enum DeviceState { Active, ShuttingDown, Offline, Updating }

    struct Device {
        address owner;
        bytes32 firmwareHash;
        DeviceState state;
        uint256 lastHeartbeat;
        uint256 shutdownInitiated;
        uint256 pendingDataFlush;
        bool hasCriticalLoad;
    }

    struct FirmwareUpdate {
        bytes32 newFirmwareHash;
        address proposer;
        uint256 proposedAt;
        bool applied;
        uint256 requiredConfirmations;
        uint256 confirmationCount;
    }

    mapping(uint256 => Device) public devices;
    mapping(uint256 => FirmwareUpdate) public pendingUpdates;
    mapping(uint256 => mapping(address => bool)) public confirmations;

    uint256 public deviceCount;
    uint256 public constant SHUTDOWN_GRACE_PERIOD = 30 seconds;
    uint256 public constant HEARTBEAT_TIMEOUT = 5 minutes;
    uint256 public constant MIN_FLUSH_WINDOW = 10 seconds;

    address public admin;

    event DeviceRegistered(uint256 indexed deviceId, address owner);
    event ShutdownInitiated(uint256 indexed deviceId, uint256 timestamp);
    event FirmwareUpdateProposed(uint256 indexed deviceId, bytes32 newHash);
    event FirmwareApplied(uint256 indexed deviceId, bytes32 newHash);
    event DataFlushed(uint256 indexed deviceId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyDeviceOwner(uint256 deviceId) {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        _;
    }

    modifier deviceExists(uint256 deviceId) {
        require(devices[deviceId].owner != address(0), "Device not found");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerDevice(bytes32 firmwareHash) external returns (uint256) {
        uint256 deviceId = ++deviceCount;
        devices[deviceId] = Device({
            owner: msg.sender,
            firmwareHash: firmwareHash,
            state: DeviceState.Active,
            lastHeartbeat: block.timestamp,
            shutdownInitiated: 0,
            pendingDataFlush: 0,
            hasCriticalLoad: false
        });
        emit DeviceRegistered(deviceId, msg.sender);
        return deviceId;
    }

    function heartbeat(uint256 deviceId) external onlyDeviceOwner(deviceId) {
        devices[deviceId].lastHeartbeat = block.timestamp;
    }

    function setCriticalLoad(uint256 deviceId, bool critical) external onlyDeviceOwner(deviceId) {
        devices[deviceId].hasCriticalLoad = critical;
    }

    function initiateGracefulShutdown(uint256 deviceId) external onlyDeviceOwner(deviceId) deviceExists(deviceId) {
        Device storage device = devices[deviceId];
        require(device.state == DeviceState.Active, "Device not active");

        device.state = DeviceState.ShuttingDown;
        device.shutdownInitiated = block.timestamp;
        device.pendingDataFlush = block.timestamp + MIN_FLUSH_WINDOW;

        emit ShutdownInitiated(deviceId, block.timestamp);
    }

    function completeDataFlush(uint256 deviceId) external onlyDeviceOwner(deviceId) {
        Device storage device = devices[deviceId];
        require(device.state == DeviceState.ShuttingDown, "Not shutting down");
        require(block.timestamp >= device.pendingDataFlush, "Flush window not elapsed");

        device.pendingDataFlush = 0;
        emit DataFlushed(deviceId);
    }

    function proposeFirmwareUpdate(
        uint256 deviceId,
        bytes32 newFirmwareHash,
        uint256 requiredConfirmations
    ) external onlyAdmin deviceExists(deviceId) {
        require(requiredConfirmations > 0 && requiredConfirmations <= 10, "Invalid confirmations");

        pendingUpdates[deviceId] = FirmwareUpdate({
            newFirmwareHash: newFirmwareHash,
            proposer: msg.sender,
            proposedAt: block.timestamp,
            applied: false,
            requiredConfirmations: requiredConfirmations,
            confirmationCount: 0
        });

        emit FirmwareUpdateProposed(deviceId, newFirmwareHash);
    }

    function confirmUpdate(uint256 deviceId) external deviceExists(deviceId) {
        FirmwareUpdate storage update = pendingUpdates[deviceId];
        require(!update.applied, "Already applied");
        require(update.newFirmwareHash != bytes32(0), "No pending update");
        require(!confirmations[deviceId][msg.sender], "Already confirmed");

        confirmations[deviceId][msg.sender] = true;
        update.confirmationCount++;
    }

    /**
     * @notice Apply firmware update - checks device is in safe state
     * @dev The shutdown check ensures device has completed graceful shutdown
     *      before firmware is applied. Critical load devices need extra time.
     */
    function applyFirmwareUpdate(uint256 deviceId) external onlyAdmin deviceExists(deviceId) {
        Device storage device = devices[deviceId];
        FirmwareUpdate storage update = pendingUpdates[deviceId];

        require(!update.applied, "Already applied");
        require(update.newFirmwareHash != bytes32(0), "No pending update");
        require(update.confirmationCount >= update.requiredConfirmations, "Insufficient confirmations");

        // Verify device is in safe state for update
        _verifyUpdateSafety(deviceId, device);

        // Apply the update
        device.state = DeviceState.Updating;
        device.firmwareHash = update.newFirmwareHash;
        update.applied = true;

        // Transition back to active after update
        device.state = DeviceState.Active;
        device.shutdownInitiated = 0;

        emit FirmwareApplied(deviceId, update.newFirmwareHash);
    }

    function _verifyUpdateSafety(uint256 deviceId, Device storage device) internal view {
        // Device must have initiated shutdown
        require(
            device.state == DeviceState.ShuttingDown || device.state == DeviceState.Offline,
            "Device must be shutting down or offline"
        );

        // Grace period must have elapsed
        if (device.state == DeviceState.ShuttingDown) {
            uint256 gracePeriod = SHUTDOWN_GRACE_PERIOD;
            if (device.hasCriticalLoad) {
                gracePeriod = gracePeriod * 2;
            }
            require(
                block.timestamp >= device.shutdownInitiated + gracePeriod,
                "Grace period not elapsed"
            );
        }

        // Data flush must be complete
        require(device.pendingDataFlush == 0, "Data flush pending");

        // Check heartbeat staleness - device should not be actively communicating
        // during update (indicates it's truly shut down)
        require(
            block.timestamp > device.lastHeartbeat + HEARTBEAT_TIMEOUT ||
            device.state == DeviceState.Offline,
            "Device still active"
        );
    }

    function markOffline(uint256 deviceId) external onlyAdmin deviceExists(deviceId) {
        Device storage device = devices[deviceId];
        require(
            block.timestamp > device.lastHeartbeat + HEARTBEAT_TIMEOUT,
            "Device still sending heartbeats"
        );
        device.state = DeviceState.Offline;
    }

    function emergencyOverride(uint256 deviceId, bytes32 firmwareHash) external onlyAdmin deviceExists(deviceId) {
        Device storage device = devices[deviceId];
        // Emergency: skip all checks but still require shutdown state
        require(device.state != DeviceState.Active, "Cannot override active device");
        device.firmwareHash = firmwareHash;
        device.state = DeviceState.Active;
        device.shutdownInitiated = 0;
        emit FirmwareApplied(deviceId, firmwareHash);
    }
}
